insert into cars (id, title, brand, model, grade, year, body, fuel, transmission, drive, engine, mileage, seats, color, condition, auction, reg, price, featured, status, show_home, photos, tagline, about, features) values ('corolla-cross-z-2023', 'Corolla Cross Z', 'Toyota', 'Corolla Cross', 'Z Package', 2023, 'SUV', 'Hybrid', 'Automatic', '2WD', '1798 cc', '12,400 km', 5, 'Platinum White Pearl', 'Recondition', 'Grade 4.5 / B', 'Fresh registration', 4850000, true, 'available', true, '["/img/b575980568e41f90.jpg","/img/48ce34dd5ea18d3e.jpg","/img/75b45e672be62f83.jpg"]', 'Top-grade Corolla Cross with full aero kit, panoramic roof and genuinely low mileage.', 'This is the flagship Z grade, the one buyers ask for by name. It came out of the auction with a complete aero kit already fitted, a panoramic roof and the hybrid drivetrain that returns real economy in Rajshahi traffic. Mileage is unusually low for the year and the sheet shows no structural repair history.', '["Full aero body kit","Panoramic glass roof","Toyota Safety Sense","360° camera system","Half-leather interior","Push start / smart entry","Dual-zone climate","18\" alloy wheels"]') on conflict (id) do update set title = excluded.title, brand = excluded.brand, model = excluded.model, grade = excluded.grade, year = excluded.year, body = excluded.body, fuel = excluded.fuel, transmission = excluded.transmission, drive = excluded.drive, engine = excluded.engine, mileage = excluded.mileage, seats = excluded.seats, color = excluded.color, condition = excluded.condition, auction = excluded.auction, reg = excluded.reg, price = excluded.price, featured = excluded.featured, status = excluded.status, show_home = excluded.show_home, photos = excluded.photos, tagline = excluded.tagline, about = excluded.about, features = excluded.features;
insert into cars (id, title, brand, model, grade, year, body, fuel, transmission, drive, engine, mileage, seats, color, condition, auction, reg, price, featured, status, show_home, photos, tagline, about, features) values ('corolla-cross-s-2022', 'Corolla Cross S Package', 'Toyota', 'Corolla Cross', 'S Package', 2022, 'SUV', 'Hybrid', 'Automatic', '2WD', '1798 cc', '28,900 km', 5, 'White with black roof', 'Recondition', 'Grade 4 / B', 'Fresh registration', 4250000, false, 'available', true, '["/img/48ce34dd5ea18d3e.jpg","/img/b575980568e41f90.jpg","/img/75b45e672be62f83.jpg"]', 'Same platform and hybrid engine as the Z, several lakh less. The sensible buy.', 'The S Package sits one step below the Z but keeps almost everything you actually use day to day: the body kit, the camera system and the black contrast roof. If the Z stretches the budget, this is the smarter car for the money.', '["Front and rear aero kit","Black contrast roof","Reverse camera","Toyota Safety Sense","Fabric and leather trim","Push start / smart entry","Auto climate control","17\" alloy wheels"]') on conflict (id) do update set title = excluded.title, brand = excluded.brand, model = excluded.model, grade = excluded.grade, year = excluded.year, body = excluded.body, fuel = excluded.fuel, transmission = excluded.transmission, drive = excluded.drive, engine = excluded.engine, mileage = excluded.mileage, seats = excluded.seats, color = excluded.color, condition = excluded.condition, auction = excluded.auction, reg = excluded.reg, price = excluded.price, featured = excluded.featured, status = excluded.status, show_home = excluded.show_home, photos = excluded.photos, tagline = excluded.tagline, about = excluded.about, features = excluded.features;
insert into cars (id, title, brand, model, grade, year, body, fuel, transmission, drive, engine, mileage, seats, color, condition, auction, reg, price, featured, status, show_home, photos, tagline, about, features) values ('chr-hybrid-pearl-2020', 'C-HR Hybrid — Pearl Two Tone', 'Toyota', 'C-HR', 'G Package', 2020, 'Crossover', 'Hybrid', 'Automatic', '2WD', '1797 cc', '37,800 km', 5, 'Pearl white / black two tone', 'Recondition', 'Grade 4.5 / B', 'Fresh registration', 3550000, true, 'available', true, '["/img/2680e5d8ab1441a7.jpg","/img/c7d08fd9870f8807.jpg","/img/75b45e672be62f83.jpg"]', 'High-grade C-HR with the full black aero kit, gloss alloys and premium interior trim.', 'The sharpest looking car on the lot. Factory pearl white over black cladding with the complete aero package, and the paint is original, not a respray. The hybrid system does most of the low-speed work on battery, so city fuel bills stay low.', '["Hybrid drivetrain","Full black aero kit","4-camera surround view","Panoramic roof","Half-leather interior","Push start / smart entry","Blind spot monitor","18\" gloss black alloys"]') on conflict (id) do update set title = excluded.title, brand = excluded.brand, model = excluded.model, grade = excluded.grade, year = excluded.year, body = excluded.body, fuel = excluded.fuel, transmission = excluded.transmission, drive = excluded.drive, engine = excluded.engine, mileage = excluded.mileage, seats = excluded.seats, color = excluded.color, condition = excluded.condition, auction = excluded.auction, reg = excluded.reg, price = excluded.price, featured = excluded.featured, status = excluded.status, show_home = excluded.show_home, photos = excluded.photos, tagline = excluded.tagline, about = excluded.about, features = excluded.features;
insert into cars (id, title, brand, model, grade, year, body, fuel, transmission, drive, engine, mileage, seats, color, condition, auction, reg, price, featured, status, show_home, photos, tagline, about, features) values ('chr-hybrid-red-2020', 'C-HR Hybrid — Red Wine', 'Toyota', 'C-HR', 'G Package', 2020, 'Crossover', 'Hybrid', 'Automatic', '2WD', '1797 cc', '41,200 km', 5, 'Red Wine Metallic', 'Recondition', 'Grade 4 / B', 'Fresh registration', 3390000, false, 'available', true, '["/img/c7d08fd9870f8807.jpg","/img/2680e5d8ab1441a7.jpg","/img/75b45e672be62f83.jpg"]', 'Sporty hybrid crossover in a red wine metallic that almost never lands in Bangladesh.', 'The C-HR is the easiest car here to live with in a city. Compact footprint, light steering, and a hybrid system that keeps running costs down. This unit is in the red wine metallic, a colour we see maybe once a year at auction.', '["Hybrid drivetrain","Panoramic roof","Reverse camera","Two-tone black roof","Cruise control","Push start / smart entry","Auto climate control","LED headlamps"]') on conflict (id) do update set title = excluded.title, brand = excluded.brand, model = excluded.model, grade = excluded.grade, year = excluded.year, body = excluded.body, fuel = excluded.fuel, transmission = excluded.transmission, drive = excluded.drive, engine = excluded.engine, mileage = excluded.mileage, seats = excluded.seats, color = excluded.color, condition = excluded.condition, auction = excluded.auction, reg = excluded.reg, price = excluded.price, featured = excluded.featured, status = excluded.status, show_home = excluded.show_home, photos = excluded.photos, tagline = excluded.tagline, about = excluded.about, features = excluded.features;
insert into cars (id, title, brand, model, grade, year, body, fuel, transmission, drive, engine, mileage, seats, color, condition, auction, reg, price, featured, status, show_home, photos, tagline, about, features) values ('yaris-cross-z-2020', 'Yaris Cross Z Leather', 'Toyota', 'Yaris Cross', 'Z Leather', 2020, 'SUV', 'Hybrid', 'Automatic', '2WD', '1490 cc', '33,600 km', 5, 'White with black roof', 'Recondition', 'Grade 4 / B', 'Fresh registration', 3180000, false, 'available', true, '["/img/66af8533f89990ee.jpg","/img/48ce34dd5ea18d3e.jpg","/img/75b45e672be62f83.jpg"]', 'Compact SUV in the top Z Leather trim — comfort, economy and a high seating position.', 'Small enough for narrow roads, tall enough for broken ones. The Z Leather grade adds heated leather seats, a power tailgate and the full driver-assist suite. This is the car we recommend most often to buyers stepping up from a sedan.', '["Leather seats","Power tailgate","Toyota Safety Sense","Black contrast roof","Reverse camera","Push start / smart entry","Auto climate control","17\" alloy wheels"]') on conflict (id) do update set title = excluded.title, brand = excluded.brand, model = excluded.model, grade = excluded.grade, year = excluded.year, body = excluded.body, fuel = excluded.fuel, transmission = excluded.transmission, drive = excluded.drive, engine = excluded.engine, mileage = excluded.mileage, seats = excluded.seats, color = excluded.color, condition = excluded.condition, auction = excluded.auction, reg = excluded.reg, price = excluded.price, featured = excluded.featured, status = excluded.status, show_home = excluded.show_home, photos = excluded.photos, tagline = excluded.tagline, about = excluded.about, features = excluded.features;
insert into home_content (id, hero, trust, inventory, process, faq, cta, contact) values (1, '{"kicker":"Rajshahi · Bangladesh","line1":"Japan Recondition","line2":"& New Cars","line3":"Sales Center","lede":"Hand-picked Japanese vehicles, auction-verified and fully inspected. Bank loan or cash — we handle import, registration and after-sales, start to finish.","cta1":"View Available Cars","cta2":"Ask on WhatsApp","assures":["Auction sheet on request","Bank loan support","Warranty included"],"leadTitle":"Get your price today","leadSub":"Tell us what you''re after — we''ll reply with options and full pricing.","stats":[{"n":"500","suffix":"+","label":"Cars Sold"},{"n":"10","suffix":"+","label":"Years Experience"},{"n":"100","suffix":"%","label":"Satisfied Customers"},{"n":"24","suffix":"/","label":"7 Customer Support"}]}', '["Auction-verified vehicles","Bank loan facility","Cash purchase discounts","Warranty included","Import & registration handled","After-sales support","Trade-in valuations","Custom car sourcing"]', '{"kicker":"Available cars","title":"In stock right now","sub":"Every unit is hand-selected from Japanese auctions, thoroughly inspected, and delivered with warranty. Photos are of the actual vehicles.","noteTitle":"Looking for a specific model?","noteText":"Tell us the model, grade, year and budget — we source it directly from Japanese auctions and quote you the full landed cost before you commit.","noteBtn":"Request a custom order"}', '{"kicker":"How it works","title":"From auction to your driveway","sub":"Four steps, no surprises. Scroll to take the drive — you''ll know the cost, condition and timeline before any money moves.","steps":[{"title":"Choose your car","text":"Pick from ready stock in Rajshahi, or tell us the exact model and grade to source from Japan."},{"title":"Verify the condition","text":"Review the auction sheet and inspection report, then see the car in person at our showroom."},{"title":"Choose how to pay","text":"Cash for a better price, or let us arrange bank financing with quick approval."},{"title":"Drive it home","text":"We handle registration and hand over the keys — with warranty and after-sales support."}]}', '{"kicker":"Questions, answered","title":"What buyers ask us most","note":"Still unsure about something? Send us a message and we''ll answer honestly — even if the answer is \"this car isn''t right for you.\"","noteBtn":"Ask us anything","items":[{"q":"What exactly is a \"reconditioned\" car?","a":"It''s a used vehicle imported from Japan, then prepared for sale here. Japanese cars are typically well-maintained with low mileage, so a reconditioned unit gives you near-new quality at a considerably lower price than a brand-new import."},{"q":"Can I see the auction sheet before buying?","a":"Yes. Ask us for the auction sheet and inspection details of any unit in stock. We''d rather you check the grade and condition report carefully than buy on trust alone."},{"q":"Do you help arrange a bank loan?","a":"We do. We work with all major banks in Bangladesh and can guide you through the paperwork and approval process. Use the estimator above for a rough monthly figure, then message us for a bank-confirmed quote."},{"q":"Is registration and paperwork included?","a":"We handle the import and registration process for you, so you receive a road-ready car. We''ll walk you through every document and cost involved before you commit."},{"q":"What happens after I buy — is there a warranty?","a":"Every car comes with warranty coverage, plus after-sales support and maintenance. You can reach us on WhatsApp any time, including outside showroom hours."},{"q":"Can I trade in my current car?","a":"Yes. Send us photos and details of your current vehicle on WhatsApp and we''ll give you a valuation, which can go straight towards your next car."}]}', '{"kicker":"Ready when you are","title":"Let''s find the right car for you","text":"Visit the showroom in Terokhadia, or message us and we''ll send options that match your budget today.","btn1":"Call 01944755111","btn2":"Get directions"}', '{"kicker":"Contact us","title":"Come in, or just message us","intro":"No pressure and no rush — tell us your budget and we''ll show you what genuinely fits.","waTitle":"WhatsApp is the fastest way","waText":"Send a message and we''ll reply with real options, real prices and the auction sheet.","helpItems":["Car availability and pricing","Bank loan and financing options","Import and registration process","Trade-in valuations","Inspection and warranty details"]}') on conflict (id) do update set hero = excluded.hero, trust = excluded.trust, inventory = excluded.inventory, process = excluded.process, faq = excluded.faq, cta = excluded.cta, contact = excluded.contact, updated_at = now();
insert into site_settings (id, phone, whatsapp, address, hours_week, hours_fri, emergency) values (1, '01944755111', '8801944755111', 'Terokhadia, Rajshahi-6000, Bangladesh', '9:00 AM – 8:00 PM', '2:00 PM – 8:00 PM', 'Emergency 24/7 via WhatsApp') on conflict (id) do update set phone = excluded.phone, whatsapp = excluded.whatsapp, address = excluded.address, hours_week = excluded.hours_week, hours_fri = excluded.hours_fri, emergency = excluded.emergency, updated_at = now();
